UPDATE gym_coach
name = #{name}, phone = #{phone}, specialties = #{specialties}, bio = #{bio}, avatar = #{avatar}, status = #{status}, gender = #{gender}, experience_years = #{experienceYears}, certification = #{certification}, hourly_rate = #{hourlyRate}, update_time = #{updateTime}
